   declarat ací perquè no depenga de l'etiqueta que pinte el títol. */
.sp-card-title {
  font-size: var(--sdp-text-h5);
  color: var(--sdp-accio-text);
  font-weight: 800;
  line-height: var(--sdp-leading-titol);
