   és de 24px com les icones del sistema i el botó es fa cercle. */
.sp-card-connect-plus {
  display: none;
  font-size: 24px;
  line-height: 1;
}

@container (max-width: 360px) {
  .sp-card-connect-text {
    display: none;
  }
  .sp-card-connect-plus {
    display: inline;
  }
  .btn-connectar.sp-card-connect {
    width: var(--sdp-touch-comode);
