  .sp-card-connect-text {
    display: none;
  }
  .sp-card-connect-plus {
    display: inline;
  }
  .btn-connectar.sp-card-connect {
    width: var(--sdp-touch-comode);
    padding: 0;
  }
}

/* P6 (directriu 261003_2325 del Mestre) · EL QUADRAT de 128 px és l'únic
   indicador de la targeta: la data, el preu o la icona. Fons gris grafit
   (el pedra-700, decisió d'usabilitat del Mestre per no fer un pegat
   negre tan brusc), i lletra clara (--sdp-crom-text): la closca no canvia
   entre clar i fosc, i el quadrat tampoc. Revisió de P6 · El grafit arriba
   pel crom, mai per la rampa (llei de tokens.css: cap component escriu
   --sdp-pedra-*): --sdp-workspace-nav-fons és el fons de la columna de
   navegació (--sdp-crom-capcalera, el mateix grafit 700) i el hover,
   --sdp-crom-capcalera-clara (el grafit 600). Mateix píxel. Contrastos WCAG:
     · --sdp-crom-text sobre el grafit: AAA; l'any amb opacitat 0,8: AA;
     · en passar-hi per damunt (botó), sobre el grafit clar: 7,28:1 · AAA;
     · anell de focus (base.css, 3px a 2px de distància, sobre la targeta):
       --sdp-focus sobre --sdp-fons-targeta, 9,21:1 en clar i 8,28:1 en fosc;
     · en fosc, la targeta (pedra 850) i el quadrat (pedra 700) destaquen bé
       així que la vora --sdp-vora-control ajuda a marcar el límit.
   Fase C (pla 261004_0050, Kowalski) · Fora el `transition: all` de 0,2s,
   l'elevació de −2px i el canvi d'ombra: l'ombra --sdp-ombra-1 es queda
   (Q6) i no s'anima. El botó respon amb el color del crom en passar-hi per
   damunt i amb l'escala del sistema (0,97) en prémer. <time> i <div> no
   responen: la transició no hi fa res. */
.sp-card-calendar-badge {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  float: right;
  margin-left: var(--sdp-space-4);
  margin-bottom: var(--sdp-space-3);
  width: 128px;
  height: 128px;
  background-color: var(--sdp-workspace-nav-fons);
  color: var(--sdp-crom-text);
  border-radius: var(--sdp-radi-xl);
  box-shadow: var(--sdp-ombra-1);
  border: 2px solid transparent;
  transition: background-color var(--sdp-t), transform var(--sdp-durada-premut) var(--sdp-corba-eixida);
}

@media (hover: hover) and (pointer: fine) {
  button.sp-card-calendar-badge:hover {
    background-color: var(--sdp-crom-capcalera-clara);
  }
  /* Cap hover baixa de banda (Q1, 261004): l'any, al 80 % d'opacitat, feia
     7,84:1 sobre el grafit i 5,37:1 sobre el grafit clar del hover. Opac,
     7,28:1 · AAA. Regla nova: la del hover del quadrat no canvia. */
  button.sp-card-calendar-badge:hover .sp-card-calendar-badge__any {
    opacity: 1;
  }
}

button.sp-card-calendar-badge:active {
  transform: scale(var(--sdp-escala-premut));
}

/* El quadrat que es pot prémer puja damunt del vel enllaç de la targeta
   (.sp-card-link-overlay, z-index 1), com la resta de peces interactives
   (la llista de z-index 2 de més amunt). Sense, el vel se l'emportava: el
   clic obria la targeta i el hover i el premut no hi arribaven mai
   (comprovat al navegador: elementFromPoint tornava el vel). El <time> i
   el <div> no es toquen. */
button.sp-card-calendar-badge {
  position: relative;
  z-index: 2;
}

:root[data-theme="dark"] .sp-card-calendar-badge,
:host([data-theme="dark"]) .sp-card-calendar-badge {
  border-color: var(--sdp-vora-control);
}

.sp-card-calendar-badge__dia {
  font-size: 3.5rem;
  font-weight: 900;
  line-height: 1;
  font-family: var(--sdp-font);
}

/* P6 · Un preu (data-mida, UniversalCard.midaDelPreu) cap sencer al quadrat:
   la lletra baixa per trams i, si encara no hi cap, parteix línia dins. */
.sp-card-calendar-badge__dia[data-mida] {
  max-width: 100%;
  padding-inline: var(--sdp-space-2);
  text-align: center;
  overflow-wrap: anywhere;
  letter-spacing: -0.01em;
}
.sp-card-calendar-badge__dia[data-mida="mitjana"] { font-size: 2.25rem; }
.sp-card-calendar-badge__dia[data-mida="menuda"] { font-size: 1.625rem; }
.sp-card-calendar-badge__dia[data-mida="minima"] { font-size: 1.25rem; line-height: 1.15; }

/* D-C (ordre del Mestre, 261004) · el mes i l'any, al graó més pròxim de
   l'escala: 17,6 → 18px (--sdp-text-base) i 14,4 → 14px (--sdp-text-meta);
   el respir entre ells, de 2 a 4px (--sdp-space-1). Hi cap: 56 + 27 + 21 +
   4 = 108px dins dels 124 interiors del quadrat. */
.sp-card-calendar-badge__mes {
  font-size: var(--sdp-text-base);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.sp-card-calendar-badge__any {
  font-size: var(--sdp-text-meta);
  font-weight: 500;
  opacity: 0.8;
  margin-top: var(--sdp-space-1);
}

.btn-taronja-fort {
  background: var(--sdp-crom-realc);
  color: var(--sdp-sobre-accent);
  font-weight: 700;
  border: none;
  height: var(--sdp-space-12);
  padding: 0 var(--sdp-space-4);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--sdp-radi-boto);
  font-size: var(--sdp-text-meta);
  line-height: var(--sdp-leading-snug);
  cursor: pointer;
  transition: background-color var(--sdp-t);
  white-space: nowrap;
}

/* Fase C (pla 261004_0050) · cap hover engrandix: fora l'escala d'1,02.
   El retorn és el vel del crom, i només amb ratolí. */
@media (hover: hover) and (pointer: fine) {
  .btn-taronja-fort:hover {
    background: var(--sdp-crom-hover);
  }
}

.btn-taronja-fort.active {
  background: var(--sdp-accent);
}

.btn-taronja-fort.btn-taronja-fort--icon {
  padding: 0;
  width: var(--sdp-space-12);
  border-radius: 50%;
}



.pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sdp-space-2);
  padding: var(--sdp-space-2) var(--sdp-space-4);
  border-radius: var(--sdp-radi-pastilla);
  font-weight: 700;
  font-size: var(--sdp-text-meta);
  cursor: pointer;
  border: 1px solid var(--sdp-vora);
  background: var(--sdp-fons-targeta);
  color: var(--sdp-text-cos);
  transition: background-color var(--sdp-t), border-color var(--sdp-t), color var(--sdp-t), transform var(--sdp-durada-premut) var(--sdp-corba-eixida);
}

.pill--primary {
  background: var(--sdp-accio-control);
  color: var(--sdp-sobre-accio);
  border-color: var(--sdp-accio-control);
}

.pill--accent {
  background: var(--sdp-accent);
  color: var(--sdp-sobre-accent);
  border-color: var(--sdp-accent);
}

/* Fase A i B (pla 261004_0050) · La transició nomena les propietats (cap
   `all`) i el hover només viu amb ratolí. Els hovers van junts darrere de
   les varietats: tenen més especificitat que elles, el resultat no canvia.
   El brightness de l'accent es queda (7,6:1 amb la lletra fosca; el token
   --sdp-accent-hover en clar en fa 5,42) i ja no s'anima. */
@media (hover: hover) and (pointer: fine) {
  .pill:hover {
    background: var(--sdp-fons-subtil);
  }

  .pill--primary:hover {
    background: var(--sdp-accio-control-hover);
  }

  .pill--accent:hover {
    filter: brightness(1.1);
  }
}

/* Fase C · Les píndoles que es poden prémer (botó o enllaç) fan l'escala del
   sistema. Les d'ara són <span> informatius: no responen. */
button.pill:active:not(:disabled),
a.pill:active {
  transform: scale(var(--sdp-escala-premut));
}

.badge-row {
  display: flex;
  gap: var(--sdp-space-2);
  margin-bottom: var(--sdp-space-4);
  flex-wrap: wrap;
}

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 24px;
  padding: 0 var(--sdp-space-3);
  border-radius: var(--sdp-radi-pastilla);
  font-size: var(--sdp-text-meta);
  font-weight: 800;
  letter-spacing: 0.05em;
  background: var(--sdp-fons-subtil);
  color: var(--sdp-text-titol);
  white-space: nowrap;
}

/* Els modificadors d'estat van DESPRÉS del segon .badge: mateixa capa i
   mateixa especificitat, guanya l'ordre de font. Abans vivien davant i
   eixe bloc els pintava tots de gris neutre. */
.badge-success {
  background: var(--sdp-exit-fons);
  color: var(--sdp-exit-text);
}

.badge-warning {
  background: var(--sdp-avis-fons);
  color: var(--sdp-avis-text);
}

.badge-info {
  background: var(--sdp-info-fons);
  color: var(--sdp-info-text);
}

.devices-panel__head .badge-row,
.card__body .badge-row {
  justify-content: center;
  margin-top: var(--sdp-space-3);
}

.devices-panel__body .card__body .badge-row {
  align-content: center;
  justify-content: center;
  margin-top: 0;
}

.notes-editor .badge-row {
  margin-top: var(--sdp-space-3);
}

.card--soft .split-grid .sp-card-labels {
  margin-top: 0;
  margin-bottom: var(--sdp-space-3);
  justify-content: center;
}

.editor-toolbar .btn-icon {
  color: var(--sdp-crom-text);
}

@media (hover: hover) and (pointer: fine) {
  .editor-toolbar .btn-icon:hover {
    background: var(--sdp-crom-hover);
    color: var(--sdp-crom-text);
  }
}

.btn-icon {
  width: var(--sdp-touch);
  height: var(--sdp-touch);
  padding: 0;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
}

.btn-icon svg,
.btn-publish svg {
  flex: none;
}

.btn-publish {
  background: var(--sdp-accio);
  color: var(--sdp-sobre-accio);
  font-weight: 700;
  padding: var(--sdp-space-2) var(--sdp-space-5);
}

@media (hover: hover) and (pointer: fine) {
  .btn-publish:hover {
    background: var(--sdp-accio-hover);
  }

  .editor-toolbar .btn-icon:hover {
    outline: 1px solid currentColor;
    outline-offset: -2px;
  }
}

/* ═══ CONTROLS DE BARRA · LLEI DE PEDRA SECA ═════════════════════════
   Una sola família per a tots els botons que viuen damunt d'una barra de
   color: la blava de navegació de pàgina (header.bar-blue), la taronja
   d'autoria (section.bar-orange) i el peu blau de la UniversalCard.
   Dues formes, i prou:
     · ICONA  → IconButton (.sp-card-action) i .btn-icon-orange: CERCLE.
     · TEXT   → ActionControl «Connectar» (.btn-connectar) i
                DateTimeControl (.btn-date-time): PASTILLA.
   Totes comparteixen alçada (--sdp-touch-comode, 48px), radi
   (--sdp-radi-boto, l'àlies de tokens.css que resol a la pastilla: regla
   definitiva del Mestre, 260927 vespre; només la barra principal i la
   primera columna són rectangles purs), hover (vel blanc --sdp-crom-hover, que és
   visible sobre qualsevol color massís) i cap transform. Les icones són
   de 24px com la resta del sistema (.icon), mai 30px «a ull».
   Els components viuen a PedraSeca/atoms/controls.jsx; ací només la pell.
   T51 (ordre del Mestre, 260928) · El botó d'emoticona de l'espai central de
   la barra taronja (EmoticonaBarra, .sdp-emoticona-barra--boto) és de la
   mateixa família i forma que .btn-icon-orange: cercle de vel fosc i icona
   BLANCA (la ploma de lucide quan encara no hi ha emoticona). */
.sp-card-action,
.btn-icon-orange,
.sdp-emoticona-barra--boto,
.btn-connectar,
.btn-date-time {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  min-width: var(--sdp-touch-comode);
  height: var(--sdp-touch-comode);
  min-height: var(--sdp-touch-comode);
  margin: 0;
  border: 0;
  border-radius: var(--sdp-radi-boto);
  font: inherit;
  cursor: pointer;
  opacity: 1;
  transform: none;
  transition: background-color var(--sdp-t), color var(--sdp-t);
}

/* L'hora de només lectura (DateTimeControl sense onClick pinta un <time>):
   la mateixa pastilla, però sense la mà de «clica'm» (targetes de la Consola). */
time.btn-date-time { cursor: default; }

/* Forma ICONA: cercle transparent; el vel apareix en hover. */
.sp-card-action,
.btn-icon-orange,
.sdp-emoticona-barra--boto {
  width: var(--sdp-touch-comode);
  padding: 0;
}
.sp-card-action {
  background: transparent;
  color: currentColor;
}
/* T51 (ordre del Mestre, 260928) · Les icones de la barra taronja (i de la
   caputxa de la targeta) són BLANQUES: pin, bola del món, cadenat i la ploma
   de l'espai central. Abans el blanc de .btn-icon-orange només vivia a la
   capa legacy (layout.css) i el currentColor de .sp-card-action, ací a
   `components`, el tornava negre (el pin de l'IconButton). Mateixa capa i
   darrere de .sp-card-action: guanya per ordre, sense !important. */
.btn-icon-orange,
.sdp-emoticona-barra--boto { color: var(--sdp-sobre-color); }
.sp-card-action .icon,
.btn-icon-orange .icon,
.btn-icon-orange > svg,
.sdp-emoticona-barra--boto .icon {
  width: 24px;
  height: 24px;
  stroke-width: 2;
  margin: 0;
  display: block;
  opacity: 1;
}
/* Fase B (pla 261004_0050) · el vel del hover, només amb ratolí. El premut
   (:active, just davall) és el retorn de color de tots, també al tàctil.
   Q3 del Mestre · barra blava, peu i CONNECTAR: cap transform, mai. */
@media (hover: hover) and (pointer: fine) {
  .sp-card-action:hover:not(:disabled),
  .btn-icon-orange:hover:not(:disabled),
  .sdp-emoticona-barra--boto:hover:not(:disabled) {
    background: var(--sdp-crom-hover);
    opacity: 1;
    transform: none;
  }
}
.sp-card-action:active:not(:disabled),
.btn-icon-orange:active:not(:disabled),
.sdp-emoticona-barra--boto:active:not(:disabled) {
  background: var(--sdp-crom-vora-forta);
}
.btn-icon-orange,
.sdp-emoticona-barra--boto { background: var(--sdp-crom-scroll-pista); }
.btn-icon-orange:hover:not(:disabled),
.sdp-emoticona-barra--boto:hover:not(:disabled) { background: var(--sdp-crom-scroll-puny); }
/* T51 · L'emoticona (un emoji de colors, no una icona de traç) a la mida de
   les icones de la barra, sense l'aire de línia que la desquadraria. */
.sdp-emoticona-barra__glif {
  display: block;
  font-size: var(--sdp-text-h4);
  line-height: 1;
  font-style: normal;
}
/* T51 · En lectura, l'emoticona triada a l'alçada dels cercles (la fila no
   es desquadra); sense emoticona, la cel·la conserva el seu lloc a la graella
   però no ocupa gens d'ample. */
.sdp-emoticona-barra--glif {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--sdp-touch-comode);
}
.sdp-emoticona-barra--buida { inline-size: 0; }

/* Forma TEXT: pastilla. Lletra al sòl del sistema (14px), mai 0,8rem. */
.btn-connectar,
.btn-date-time {
  padding: 0 var(--sdp-space-5);
  font-size: var(--sdp-text-meta);
  font-weight: 700;
  line-height: var(--sdp-leading-snug);
  white-space: nowrap;
}
.btn-connectar {
  background: var(--sdp-accio-control);
  color: var(--sdp-sobre-accio);
  text-transform: uppercase;
  letter-spacing: .04em;
}
@media (hover: hover) and (pointer: fine) {
  .btn-connectar:hover:not(:disabled) {
    background: var(--sdp-accio-control-hover);
    opacity: 1;
    transform: none;
  }
}
/* Fase C · Q3 · CONNECTAR respon en prémer amb color, sense transform: el
   blau del hover (blanc a 7,20:1, AAA). Al tàctil és l'únic retorn. */
.btn-connectar:active:not(:disabled) {
  background: var(--sdp-accio-control-hover);
}
.btn-date-time { padding-inline: var(--sdp-space-4); }
@media (hover: hover) and (pointer: fine) {
  .btn-date-time:hover:not(:disabled) { transform: none; }
}
/* Fase C · Q3 · la pastilla de l'hora (botó; el <time> de només lectura no
   respon) s'enfosquix en prémer: el vel negre més dens de la barra. El text
   blanc hi guanya contrast, no en perd. */
button.btn-date-time:active:not(:disabled) {
  background: var(--sdp-crom-scroll-puny-viu);
}

.sp-card-action:disabled,
.btn-icon-orange:disabled,
.btn-connectar:disabled,
.btn-date-time:disabled { cursor: default; }
/* «presentation» (sense onClick): l'atom el desactiva; no ha de semblar apagat. */
.sp-card-action:disabled { opacity: 1; }
/* T36 · Comentar i Compartir desactivats a l'editor: cap transform (família
   de barra). El hover que els pujava 1px ja no existix (Fase A, 261004):
   la regla queda de xarxa. */
.bar-blue .sp-card-actions .sp-card-action:disabled { transform: none; }

/* Trios de la barra blava (ordre del Mestre, 260924): els cercles es toquen.
   La separació la dona el mateix cercle tàctil. Sòl: --sdp-touch (48px
   des del 261004, Llei de Vida); per davall d'ací no es baixa. Les icones
   van a tocar (gap 0): de glif a glif, la cel·la sencera; al pack de
   navegació, des de T53, les fletxes s'acosten al llibre (cada glif
   s'hi acosta 4px dins de la seua cel·la, més avall). L'alçada és la mateixa
   cel·la perquè el vel de hover continue sent un cercle i no una pastilla.
   T20 (260927 nit): cada trio és un PACK que no s'encongix. En una barra
   estreta, la graella `1fr auto 1fr` d'abans deixava que els dos trios se
   solaparen; el que no cap sobreïx per la dreta, i tot es veu fins als
   336px de barra (0 de coixí + 144 + 144 + 48). El gap i el coixí són a
   layout.css; la graella de tres columnes (T37) és just davall. */
.bar-blue-left,
.bar-blue .sp-card-actions { gap: 0; }
/* T37 (ordre del Mestre, 260928) · el trio del mig (Traduir · Comentar ·
   Compartir) va centrat respecte a la barra, siga quin siga l'ample dels
   extrems (skill sdp-universal-page §1.A: «centrat matemàticament respecte
   a tota la barra»). Mana sobre el `display: flex` de layout.css perquè
   esta capa guanya a `legacy`. Els extrems són minmax(max-content, 1fr) i
   el mig max-content: amb lloc, els dos extrems fan el mateix ample i el
   trio cau al centre exacte; sense lloc, cap columna baixa del seu
   contingut (l'1fr nu d'abans, amb el `min-width: 0` de layout.css,
   s'encongia fins a 0: és la T20) i el trio s'aparta el mínim cap a la
   dreta. La col·locació va per classe i no per posició: els
   :first-child/:last-child de layout.css enviarien el trio a la columna 3
   si un dia no hi haguera CONNECTAR. */
header.bar-blue {
  display: grid;
  grid-template-columns: minmax(max-content, 1fr) max-content minmax(max-content, 1fr);
}
.bar-blue-left { grid-column: 1; justify-self: start; }
.bar-blue .sp-card-actions { grid-column: 2; justify-self: center; }
.bar-blue .btn-connectar.sp-card-connect { grid-column: 3; justify-self: end; }
.bar-blue-left .sp-card-action,
.bar-blue .sp-card-actions .sp-card-action {
  width: var(--sdp-touch);
  min-width: var(--sdp-touch);
  height: var(--sdp-touch);
  min-height: var(--sdp-touch);
}
/* T53 (ordre del Mestre, 260928) · les fletxes porten més aire dins del
   dibuix que el llibre i el trio (el traç va de x=4 a x=20 del requadre,
   icones.jsx): de tinta a tinta el pack de navegació es llegia més solt
   que el del mig. Cada fletxa s'acosta al llibre dins de la seua cel·la
   (el marge d'un costat desplaça el glif la meitat); la cel·la tàctil
   continua sent --sdp-touch i el vel del hover, el mateix cercle. */
.bar-blue-left .bar-blue-left__arrere .icon { margin-inline-start: var(--sdp-space-2); }
.bar-blue-left .bar-blue-left__endavant .icon { margin-inline-end: var(--sdp-space-2); }

/* CONNECTAR a la barra blava: mana l'amplada de la BARRA, no la de la
   finestra. Així també passa a «+» quan la pàgina viu en una columna
   estreta (Wiki, Notes) d'una pantalla gran. La @media de dalt (≤480px,
   paraula o «+») i la de layout.css (≤480px, separació i coixí) continuen
   fent de xarxa per als navegadors sense @container (Baseline 2022:
   Chrome 100 i Firefox 100). La barra no té descendents fixos: la
   taula de continguts es pinta en un portal fora d'ella. */
header.bar-blue { container-type: inline-size; }
/* T20 · un element no pot consultar el seu propi contenidor: perquè les
   regles sobre header.bar-blue (gap, coixí) responguen a l'amplària de la
   barra, el pare (.sdp-universal-page-container, del mateix ample) també és
   contenidor. Els descendents de la barra continuen consultant la barra. */
.sdp-universal-page-container { container-type: inline-size; }
/* T53 · el llindar és el de les dues xarxes (480). Amb la paraula, la barra
   demana 498 (coixí 32 + separació 48 + 144 + 144 + CONNECTAR 130; abans
   de --sdp-touch 48 eren 474): amb el llindar de 400 d'abans, CONNECTAR
   sobreeixia (la columna de l'editor de Notes en pantalles d'uns 1000). La
   paraula consulta la caixa de contingut de la barra (sense el coixí de 32):
   només torna a partir de 513px de barra, i hi cap (mesurat, 261004). */
@container (max-width: 480px) {
  .bar-blue .sp-card-connect-text { display: none; }
  .bar-blue .sp-card-connect-plus { display: inline; }
  .bar-blue .btn-connectar.sp-card-connect { width: var(--sdp-touch-comode); padding: 0; }
  /* T20 · els packs s'acosten a 8px i el coixí de la barra baixa a 8px:
     8 + 144 + 8 + 144 + 8 + 48 + 8 = 368px de barra (dues separacions, una
     per cada frontera de la graella de tres columnes). */
  header.bar-blue { gap: var(--sdp-space-2); padding: 0 var(--sdp-space-2); }
}
/* T20 · per davall de 368px de barra: packs a tocar, sense coixí, i el «+»
   a la cel·la de 48 com les icones: 144 + 144 + 48 = 336px.
   Correcció final (ordre del Mestre, 261004) · El pas era a 336, del temps
   de --sdp-touch 44 (8 + 132 + 8 + 132 + 8 + 48 + 8 = 344): amb 48, entre
   337 i 367px de barra CONNECTAR sobreeixia (el detall de la Wiki amb el
   rail de 56px: 358px de barra en una finestra de 1255; 346-350 a 768 i
   1024 quan la barra de scroll no ocupa lloc). Per davall de 336px de barra
   (un telèfon de 320, el detall de la Wiki a 375, o a 768 i 1024 amb barra
   de scroll clàssica) encara no hi cap res: decisió pendent del Mestre. */
@container (max-width: 367px) {
  header.bar-blue { gap: 0; padding: 0; }
  .bar-blue .btn-connectar.sp-card-connect {
    width: var(--sdp-touch);
    min-width: var(--sdp-touch);
    height: var(--sdp-touch);
    min-height: var(--sdp-touch);
  }
}
/* T53 · Catàleg (EspecimenControlsBarra): les mostres de la barra blava.
   Sense contenidor propi, el coixí i la separació consultarien l'ample de
   la pàgina de Disseny i no el de la mostra (a PageFrame, el pare fa el
   mateix ample que la barra). La mostra estreta, de 28rem, cau dins de la
   franja 401–474 on el llindar vell deixava sobreeixir CONNECTAR. */
.sdp-especimen__barres--contenidor { container-type: inline-size; }
.sdp-especimen__barres--estreta { inline-size: min(100%, 28rem); }
/* T51 (ordre del Mestre, 260928) · La barra taronja, com la blava (T37), és
   una graella de tres columnes: autoria · espai central (EmoticonaBarra) ·
   accions i data. Mana sobre el `display: flex` de layout.css perquè esta
   capa guanya a `legacy`. L'autoria és minmax(0, 1fr): el nom i el poble es
   retallen amb punts suspensius abans que les accions baixen del seu
   contingut, que és minmax(max-content, 1fr). Amb lloc, els dos extrems fan
   el mateix ample i l'emoticona cau al centre exacte de la barra. En
   lectura sense emoticona, la cel·la central és buida (ample 0) i la data
   continua a la dreta. La col·locació va per classe, no per posició. */
section.bar-orange {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(max-content, 1fr);
}
.bar-orange > .sp-card-author { grid-column: 1; min-width: 0; }
.bar-orange > .sdp-emoticona-barra { grid-column: 2; justify-self: center; }
.bar-orange > .bar-actions { grid-column: 3; justify-self: end; }
/* Poliment T51 (260928) · El botó d'emoticona penja directament de la barra,
   fora de .bar-actions: la correcció C15 (modules.css) no l'abastava i en
   tema fosc heretava l'anell general, ≈1,26:1 damunt del taronja (WCAG 2.4.7
   i 1.4.11). El mateix anell que la resta de la barra: el color del text. */
section.bar-orange > .sdp-emoticona-barra--boto:focus-visible { outline-color: var(--sdp-sobre-accent); }
/* T51 · La caputxa de la targeta (CardHeader) només porta espai central quan
   hi ha una emoticona triada (lectura: mai la ploma). Sense, el flex de
   sempre (Llei del Píxel); amb, la mateixa graella que la barra. */
.sp-card-header--amb-emoticona {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(max-content, 1fr);
}
.sp-card-header--amb-emoticona > .sp-card-author-link,
.sp-card-header--amb-emoticona > .sp-card-author-block { grid-column: 1; min-width: 0; }
.sp-card-header--amb-emoticona > .sdp-emoticona-barra { grid-column: 2; justify-self: center; }
.sp-card-header--amb-emoticona > .sp-card-meta { grid-column: 3; justify-self: end; }
/* T38 (ordre del Mestre, 260928) · En mòbil (finestra ≤720px: el mateix tall
   que .sdp-ocult-mobil i l'«estret» d'AppGridShell) o en columna estreta
   (pàgina de ≤400px; la blava es compacta abans, a 480px de barra, des de
   T53) la barra taronja de PÀGINA
   no es pinta: no hi ha lloc per a les dues barres i la taronja quedava
   solta, separada de la blava per la capçalera. Només la de pàgina, filla
   directa del contenidor de PageFrame.jsx: la caputxa de la UniversalCard
   (.sp-card-header) i l'espècimen de Disseny (.sdp-especimen__barres) no
   canvien. Excepció decidida pel Mestre (260928): l'editor del Perfil la
   conserva, perquè s'hi veu l'avatar (T35). Des de T40 el selector
   d'identitat ja no hi viu (és a la barra negra); si l'excepció es manté és
   decisió pendent del Mestre. Sense la taronja, les eines
   ancorades pugen a davall de la blava; al Bloc de Notes continua manant el
   top 0 de `.sdp-bloc .sdp-editor-eines` (mateixa especificitat, modules.css
   s'importa després). La @media fa de xarxa per a Chrome 100 i Firefox 100,
   que no coneixen @container. T51 · L'excepció del Perfil torna la barra
   com a graella (display: grid), no com a flex: un flex esclafaria les tres
   columnes de la barra. */
/* T24 (Revertit pel Mestre, 261004) · La barra taronja JA NO s'amaga en mòbil per preservar l'arquitectura de la UniversalPage. */
/* ── TARGETA PLANA (Llistats com Notes) ──────────────────────────────
   La previsualització viva del Bloc de Notes ha de llegir-se igual que
   la publicació real: caputxa taronja, cos centrat i peu blau.

   Per això ací NOMÉS es declara el que canvia respecte de `.sp-card`:
   la caixa perd marc, radi i ombra perquè viu dins d'una llista, i
   l'entradeta es retalla a dues línies perquè la columna és estreta.

   La resta s'hereta i no es redeclara. El taronja de `.sp-card-header`,
   l'avatar de 48px i el centrat del cos ja viuen a la targeta base;
   sobreescriure'ls ací és precisament el que trencava l'equivalència
   entre la previsualització i la publicació. */
.sp-card--pla {
  border-radius: 0;
  width: 100%;
  margin: 0;
  border: 0;
  border-bottom: 2px solid var(--sdp-vora);
  box-shadow: none;
  background: transparent;
  min-height: auto;
}
@media (hover: hover) and (pointer: fine) {
  .sp-card--pla:hover {
    box-shadow: none;
    background: var(--sdp-fons-targeta);
  }
}
}


/* Mostres del configurador cromàtic: el valor dinàmic passa pel contracte HEX6.
   La mostra és informativa; no introduïx un altre color d'acció. */
@layer components {
  .sdp-crom-panell { display: flex; flex-direction: column; gap: var(--sdp-space-4); }
  .sdp-crom-rampa { display: flex; flex-direction: column; gap: var(--sdp-space-2); }
  .sdp-crom-mostres { display: flex; gap: var(--sdp-space-1); list-style: none; margin: 0; padding: 0; }
  .sdp-crom-mostra {
    flex: 1; min-width: 0; min-height: var(--sdp-space-8);
    background-color: var(--sdp-crom-mostra);
    border-radius: var(--sdp-radi-s);
  }
  /* La preview viu en una columna flex estreta: el contingut no la força a créixer. */
  .sdp-nota-fitxa-viva { min-width: 0; }
}

/* ── T50 · TARGETA VIVA A LA DRETA DE L'EDITOR ─────────────────────────
   Decisió del Mestre (260928): «Llista + dreta si hi cap». Amb la clau
   `targetaViva` de l'adaptador (Bloc de Notes i Perfil), DocumentEditor
   embolcalla la closca en `.sdp-editor-amb-targeta`, SEMPRE (el pare de la
   closca no canvia amb l'amplària: TipTap no es remunta). L'embolcall és un
   contenidor AMB NOM: el xip i l'aside no consulten el contenidor més pròxim
   (.sdp-universal-page-container), sinó l'editor sencer.
     · Editor de 60rem o més (menús plegats): graella editor | targeta, amb
       l'aside fix i el seu propi scroll; el xip «Vista targeta» s'amaga.
     · Més estret, en mòbil i en navegadors sense @container (Baseline 2022:
       Chrome 100 i Firefox 100): cap aside; el xip obri el diàleg.
   L'embolcall fa el paper que feia la closca dins de la columna del detall
   (flex en columna, height 100%, min-height 0): les barres sticky i el
   scroll del contenidor de la pàgina continuen dins de la closca.
   `--drets`: amb la vista de drets d'autor oberta, s'amaga sencer (la closca
   ja ho estava; l'aside no s'ha de quedar al costat de CopyrightPage). */
@layer components {
  .sdp-editor-amb-targeta {
    container: sdp-editor-targeta / inline-size;
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    min-width: 0;
  }
  .sdp-editor-amb-targeta--drets { display: none; }
  .sdp-editor-amb-targeta__graella {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr);
    flex: 1 1 0;
    min-height: 0;
    min-width: 0;
  }
  .sdp-targeta-viva { display: none; }
  .sdp-targeta-viva-carta { min-width: 0; }
  /* El xip viu dins d'un altre contenidor (.sdp-universal-page-container):
     Chrome no sempre torna a avaluar-hi la consulta amb nom quan l'editor
     s'eixampla després d'haver-se estretit (el xip es quedava al costat de
     l'aside). No consulta res: hereta de la graella, filla directa del
     contenidor, una propietat que la consulta posa a `none`. Sense
     @container, la propietat no existix i el xip es veu. */
  .sdp-editor-amb-targeta .sdp-boto-targeta-viva { display: var(--targeta-viva-xip, inline-flex); }
  @container sdp-editor-targeta (min-width: 60rem) {
    .sdp-editor-amb-targeta__graella {
      grid-template-columns: minmax(0, 1fr) var(--sdp-targeta-viva-ample);
      --targeta-viva-xip: none;
    }
    .sdp-targeta-viva {
      display: block;
      min-height: 0;
      overflow-y: auto;
      padding-block: var(--sdp-space-4);
      border-inline-start: 1px solid var(--sdp-vora);
      background: var(--sdp-fons-app);
    }
  }
}

/* ── TRADUCTOR SOBIRÀ · menú de llengües i pàgina traduïda ─────────────
   Ordre del Mestre (260930 · via B). Components: universal/traduccio/
   (MenuTraduir, TraduccioPagina) i BarraBlava. Res d'ací es veu fins que
   es prem «Traduir» (Llei del Píxel).
     · El menú té la pell dels menús del Xat (.sdp-xat-menu, modules.css):
       superfície elevada, vora i l'ombra funcional --sdp-ombra-2 (Pedra
       Seca §5: un menú flotant sobre el contingut, cap ombra decorativa).
     · Penja de la barra blava i no del trio: header.bar-blue és sticky (i
       contenidor), i per tant el seu bloc contenidor. Cau just davall de la
       barra, centrat com el trio (T37): amb 14rem, no sobreïx per cap costat
       ni en la barra més estreta (308px, T20). z-index 1 dins de la barra,
       que ja passa per damunt de la taronja (--z-barra-blava).
     · L'avís «Traduït automàticament…» és una Alerta entre el títol i el cos,
       alineada amb l'article (--sdp-pad-contenidor) i sense encongir-se en
       el contenidor en columna de PageFrame.
     · L'article original amagat (hidden) no es veu encara que una capa
       posterior li pose display; la traducció és un article germà. */
@layer components {
  .bar-blue .sdp-menu-traduir {
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1;
  }
  .sdp-menu-traduir {
    inline-size: max-content;
    min-inline-size: 14rem;
    margin: 0;
    padding: var(--sdp-space-2) 0;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-elevat);
    color: var(--sdp-text-cos);
    box-shadow: var(--sdp-ombra-2);
    text-align: start;
  }
  .sdp-menu-traduir__item {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    inline-size: 100%;
    min-block-size: var(--sdp-touch);
    padding: 0 var(--sdp-space-4);
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: start;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-menu-traduir__item:hover { background: var(--sdp-fons-subtil); }
  }
  /* Dins de la barra blava, l'anell de focus és el de la barra (base.css,
     sobre blau): damunt de la superfície clara del menú, el del sistema. */
  .sdp-menu-traduir__item:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: -2px; }
  .sdp-menu-traduir__marca { flex: none; inline-size: 1.25rem; block-size: 1.25rem; }
  .sdp-menu-traduir__separador { margin-block: var(--sdp-space-2); border-block-start: 1px solid var(--sdp-vora); }

  .sdp-universal-page-container > .sdp-avis-traduccio {
    flex: none;
    margin-inline: var(--sdp-pad-contenidor);
  }
  article.content-wrapper[hidden] { display: none; }
}

/* ── P5 · LES PORTES DE LA TARGETA DE DOBLE ACCIÓ (Onada 4, 261003) ────
   PRD «Control amb targetes il·lustrades de doble acció», aprovat pel
   Mestre, amb l'ESMENA 261003 22:34 (directrius 2234 i 2245): la targeta
   amb portes és la UniversalCard de sempre (marge, sostre de 500px, boina,
   imatge i cos), dins de la graella de sempre (.sdp-card-grid). Ací només hi
   ha les portes, al final del cos (PortesTargeta.jsx). Additiu i limitat a
   dues classes noves, .sp-card-portes i .sp-card-porta. Cap regla existent
   canvia (Llei del Píxel): .sp-card, .sp-card-body, .sp-card--action,
   .sp-card-link-overlay, .sdp-card-grid i .sdp-boto continuen com eren.
   Bloc @layer components posterior a .sp-card i a .sdp-boto: amb la mateixa
   especificitat, guanya per ordre de font. Mai sense capa (la fuga
   reparada de més amunt).
     · Les portes: una al costat de l'altra quan caben i, si no, apilades.
       L'ordre és el del DOM: Publicar i Saber-ne més.
     · La porta: la pell de Boto amb menys coixí lateral i salt de línia
       permés (llengües llargues, text al 200%), 44px d'alt com a mínim. */
@layer components {
  .sp-card-portes {
    display: flex;
    flex-wrap: wrap;
    gap: var(--sdp-space-2);
  }
  .sp-card-porta {
    flex: 1 1 9rem;
    gap: var(--sdp-space-1);
    min-height: var(--sdp-touch-min);
    padding-inline: var(--sdp-space-1);
    text-align: center;
    overflow-wrap: anywhere;
  }
}

/* ── P6 · EL GRAN BOTÓ «PUBLICAR» DE LES SIS PÀGINES (directriu 261003_2325,
   confirmació 4) ── La porta Publicar de la targeta, al final del text de
   la seua UniversalPage (PublicarDeLaPagina.jsx), amb la pell de Boto gran i
   ple (sdp-boto--gran, sdp-boto--ple). Ací només l'aire de dalt i de baix,
   perquè no s'apegue al darrer paràgraf ni a la navegació de baix. */
@layer components {
  .sdp-pagina-accio {
    margin-block: var(--sdp-space-8) var(--sdp-space-10);
  }
}

/* ── SETENA PASSADA · PREMUT, AAA I BANCAL (pla 261004_0050, Q1-Q8) ─────
   Regles NOVES. Cap regla fixada per les proves de capes canvia: .sdp-boto,
   .sp-card, .sp-card--action, .sp-card-link-overlay i el peu del diàleg
   continuen com eren. Amb la mateixa especificitat, este bloc guanya per
   ordre de font.
     · Premut (Kowalski): l'escala del sistema (--sdp-escala-premut, 0,97)
       en 100ms amb la corba d'eixida. La transició es declara en repòs:
       el gest es pot interrompre. Amb moviment reduït i al Bancal l'escala
       val 1 (tokens.css).
     · AAA (Q1, sempre): el hover de perill en fosc.
     · Colors forçats: la vora de la bafarada (l'anell, a base.css).
     · Bancal (data-contrast="bancal"): cap text translúcid. */
@layer components {
  /* El repòs de .sdp-boto porta també el transform. PerfilShell.css (mateixa
     capa, després) declara la seua, amb el transform: dins del Perfil mana. */
  .sdp-boto {
    transition: background-color var(--sdp-t), border-color var(--sdp-t), transform var(--sdp-durada-premut) var(--sdp-corba-eixida);
  }
  .sdp-boto:active:not(:disabled):not([aria-disabled="true"]) {
    transform: scale(var(--sdp-escala-premut));
  }
  /* La porta inerta (aria-disabled, «en obres») també respon en prémer:
     fa una acció, el toast que ho explica. */
  .sdp-boto[aria-disabled="true"]:active {
    transform: scale(var(--sdp-escala-premut));
  }

  /* AAA (Q1) · Hover de perill en fosc. El fons del hover és
     --sdp-error-text, que en fosc és un rosa clar: amb la lletra blanca feia
     1,70:1. No hi ha cap roig fosc semàntic en fosc, i el fons del peu del
     diàleg el fixa una prova (DialegEsborrarNota.capes.test.js): es canvia
     la lletra, --sdp-text-invers (la roca en fosc), 11,39:1 · AAA. El fons
     es repetix perquè dins del Perfil el hover blau de PerfilShell.css no
     quede amb la lletra fosca (2,69:1). En clar no canvia res: blanc sobre
     el roig fort, 9,43:1. */
  @media (hover: hover) and (pointer: fine) {
    :root[data-theme="dark"] .sdp-boto--perill:hover:not(:disabled),
    :host([data-theme="dark"]) .sdp-boto--perill:hover:not(:disabled),
    :root[data-theme="dark"] .btn-danger:hover:not(:disabled),
    :host([data-theme="dark"]) .btn-danger:hover:not(:disabled) {
      background: var(--sdp-error-text);
      color: var(--sdp-text-invers);
    }
  }
  /* El hover del peu del diàleg no porta guarda de ratolí (regla fixada):
     la lletra el seguix igual, també al tàctil. */
  :root[data-theme="dark"] .sdp-dialeg__peu .sdp-boto--perill:hover:not(:disabled),
  :host([data-theme="dark"]) .sdp-dialeg__peu .sdp-boto--perill:hover:not(:disabled) {
    background: var(--sdp-error-text);
    color: var(--sdp-text-invers);
  }

  /* Colors forçats (Windows, alt contrast): el sistema esborra les ombres.
     L'anell de la targeta sencera (una ombra interior, regla fixada) torna
     com a outline cap a dins des de base.css, sense capa: hi guanya a tots
     els components i no es repetix ací. La bafarada (role="status") no entra
     a la llista de diàlegs i menús de base.css i perd l'ombra: una vora la
     separa del contingut. CanvasText només es pinta en este mode. */
  @media (forced-colors: active) {
    .sdp-pista__bafarada {
      border: 1px solid CanvasText;
    }
  }

  /* Bancal (Q1) · Cap text translúcid. Els desactivats deixen l'opacitat i
     ho diuen amb un parell sòlid, --sdp-text-suau sobre --sdp-fons-subtil
     (9,50:1 al Bancal clar i 11,51:1 al fosc), i amb la vora de traços, que
     no depén del color. Les ombres no es toquen (Q6). */
  :root[data-contrast="bancal"] .sdp-boto:disabled,
  :host([data-contrast="bancal"]) .sdp-boto:disabled,
  :root[data-contrast="bancal"] .sdp-paginacio__pas:disabled,
  :host([data-contrast="bancal"]) .sdp-paginacio__pas:disabled,
  :root[data-contrast="bancal"] .page-btn[disabled],
  :host([data-contrast="bancal"]) .page-btn[disabled] {
    opacity: 1;
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-suau);
    border-color: var(--sdp-vora-control);
    border-style: dashed;
  }
  /* .btn no porta vora: el parell sòlid i prou. */
  :root[data-contrast="bancal"] .btn:disabled,
  :host([data-contrast="bancal"]) .btn:disabled {
    opacity: 1;
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-suau);
  }
  :root[data-contrast="bancal"] .sdp-contrasenya__ull:disabled,
  :host([data-contrast="bancal"]) .sdp-contrasenya__ull:disabled {
    opacity: 1;
    color: var(--sdp-text-suau);
  }
  /* L'any del quadrat: 0,8 d'opacitat fora del Bancal (7,84:1 sobre el
     grafit); ací, opac (11,20:1). */
  :root[data-contrast="bancal"] .sp-card-calendar-badge__any,
  :host([data-contrast="bancal"]) .sp-card-calendar-badge__any {
    opacity: 1;
  }
}

/* ── CAMPFITXER (D-D, ordre del Mestre, 261004) ───────────────────────────
   El selector de fitxers de Pedra Seca (formulari.jsx): el control natiu
   viu amagat (.sdp-nomes-lector) dins de la fila, que el posiciona, i es
   veu un Boto secundari (48px, el sòl tàctil únic) amb la línia d'estat al
   costat. Si no hi cap, l'estat baixa davall del botó. Sense :has(). */
@layer components {
  .sdp-camp-fitxer {
    position: relative;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-2) var(--sdp-space-3);
  }
  .sdp-camp-fitxer__boto {
    min-block-size: var(--sdp-touch);
  }
  .sdp-camp-fitxer__estat {
    flex: 1 1 12rem;
    min-width: 0;
    margin: 0;
    overflow-wrap: anywhere;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
}

/* Catàleg Emojis XL: dins del full que també s'injecta al Shadow DOM. */
@layer components {
  .sdp-emojis-xl details {
    margin-block: var(--sdp-space-4);
    border-block-end: 1px solid var(--sdp-vora);
  }
  .sdp-emojis-xl summary {
    min-block-size: var(--sdp-touch);
    padding-block: var(--sdp-space-2);
    color: var(--sdp-text-titol);
    font-weight: 700;
    cursor: pointer;
  }
